package api

var sswCurriculumLinenSupplyScenariosEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.scenario", source: `Bahan bantu tumpah dekat jalur pekerja; label wadah menyebut perlunya prosedur khusus.`}:                                                                 `A process chemical spills near a worker walkway; the container label indicates special procedures are required.`,
	{field: "ssw.scenario", source: `Dokumen menyebut 40 sarung bantal, tetapi hitungan aktual kurang dan segel wadah tampak rusak.`}:                                                         `The documents list 40 pillowcases, but the count is short and the container seal appears damaged.`,
	{field: "ssw.scenario", source: `Handuk tersangkut di sisi folder yang masih bergerak.`}:                                                                                                  `A towel is caught at the side of a folder that is still moving.`,
	{field: "ssw.scenario", source: `Jalur folder siap berjalan, tetapi jenis linen pada keranjang tidak cocok dengan program yang terpasang.`}:                                               `The folder line is ready to run, but the linen in the basket does not match the selected program.`,
	{field: "ssw.scenario", source: `Kontainer pengiriman berisi sisa cairan dan satu bundel bersih akan segera dimasukkan.`}:                                                                 `A shipping container has liquid residue, and a bundle of clean linen is about to be loaded.`,
	{field: "ssw.scenario", source: `Label pada wadah bahan pencuci tidak terbaca dan seorang rekan meminta menambahkan cairan berdasarkan warnanya.`}:                                        `The label on a washing-chemical container is unreadable, and a coworker asks to add liquid based on its color.`,
	{field: "ssw.scenario", source: `Noda ditemukan pada beberapa seprai yang keluar dari lini yang sama.`}:                                                                                   `Stains are found on several sheets from the same line.`,
	{field: "ssw.scenario", source: `Pada pergantian giliran, satu lini masih berhenti dan penyebabnya belum ditemukan.`}:                                                                     `At shift change, one line is still stopped and the cause has not been identified.`,
	{field: "ssw.scenario", source: `Pesanan satu pelanggan kurang dua handuk, sedangkan kelebihan handuk pelanggan berbeda tersedia.`}:                                                       `One customer's order is short two towels, while extra towels belonging to another customer are available.`,
	{field: "ssw.scenario", source: `Satu kelompok terasa masih lembap setelah siklus dan alarm mesin muncul.`}:                                                                               `A lot still feels damp after the cycle, and a machine alarm has appeared.`,
	{field: "ssw.scenario", source: `Sebuah keranjang seprai tidak memiliki label pelanggan dan keranjang lain berisi linen bersih.`}:                                                         `A basket of sheets has no customer label, while another basket contains clean linen.`,
	{field: "ssw.scenario", source: `Sebuah pakaian pasien memiliki label jenis yang luntur dan berada dekat wadah handuk hotel.`}:                                                            `A patient's garment has a faded type label and is near a container of hotel towels.`,
	{field: "ssw.response", source: `Batasi orang masuk dan beri tahu petugas berwenang. Ikuti prosedur bahan; jangan membersihkan tanpa pelatihan dan perlindungan yang sesuai.`}:            `Keep people out and notify authorized staff. Follow the chemical procedure; do not clean the spill without training and suitable protection.`,
	{field: "ssw.response", source: `Catat jumlah yang benar-benar ditemukan beserta kondisi segel dan waktu pemeriksaan; laporkan sebelum kelompok diteruskan.`}:                             `Record the actual count, seal condition, and inspection time; report the discrepancy before passing the lot on.`,
	{field: "ssw.response", source: `Gunakan prosedur penghentian jika ada bahaya langsung, jauhkan pekerja lain, dan panggil petugas berwenang; jangan menarik handuk dari alat aktif.`}:     `Use the stop procedure if there is immediate danger, keep other workers away, and call authorized staff; do not pull a towel from active equipment.`,
	{field: "ssw.response", source: `Jangan gunakan cairan itu. Amankan wadah, ikuti prosedur identifikasi bahan, dan hubungi penanggung jawab.`}:                                             `Do not use the liquid. Secure the container, follow the chemical-identification procedure, and contact the person in charge.`,
	{field: "ssw.response", source: `Jangan kirim ke area finishing sebagai hasil siap. Tahan kelompok, catat alarm, lalu minta pemeriksaan sesuai prosedur mesin.`}:                          `Do not send the lot to finishing as ready output. Hold it, record the alarm, and request an inspection under the machine procedure.`,
	{field: "ssw.response", source: `Jangan masukkan ke wadah handuk. Tahan pada tempat yang ditetapkan dan minta petugas berwenang mengidentifikasi barang tersebut.`}:                       `Do not put it in the towel container. Hold it in the designated place and ask authorized staff to identify the item.`,
	{field: "ssw.response", source: `Jangan menukar handuk antar-pelanggan. Catat selisih, tahan penyelesaian pesanan, dan minta penanggung jawab menelusuri jumlah.`}:                        `Do not substitute towels between customers. Record the discrepancy, hold order completion, and ask the person in charge to trace the quantities.`,
	{field: "ssw.response", source: `Pisahkan kedua keranjang, jangan menebak pemilik seprai, lalu laporkan agar identitas dan jalur barang dikonfirmasi.`}:                                   `Separate the two baskets, do not guess who owns the sheets, and report the issue so their identity and routing can be confirmed.`,
	{field: "ssw.response", source: `Pisahkan seprai, catat jenis cacat dan lini asal, lalu laporkan agar tahap sebelumnya diperiksa.`}:                                                       `Separate the sheets, record the defect and originating line, and report it so the preceding stage can be checked.`,
	{field: "ssw.response", source: `Tulis waktu, indikator yang terlihat, langkah aman yang telah dilakukan, dan status menunggu pemeriksaan; serahkan kepada pemimpin giliran berikutnya.`}: `Record the time, visible indicator, safe actions taken, and pending-inspection status; hand this information to the next shift lead.`,
	{field: "ssw.response", source: `Tunda masukan dan konfirmasikan program serta jalur yang benar kepada pemimpin lini.`}:                                                                   `Hold the input and confirm the correct program and route with the line lead.`,
	{field: "ssw.response", source: `Tunda pemuatan dan minta kontainer dibersihkan serta dikeringkan sesuai prosedur sebelum produk bersih dimasukkan.`}:                                     `Delay loading and have the container cleaned and dried under procedure before placing clean products inside.`,
}
